db = Database()
db.create_table("members", ["id", "name", "score"])
row = {"id": "1", "name": "Ada", "score": "07"}
db.insert("members", row)
row["name"] = "changed"
result = db.query("members", ["name"])
assert result == [{"name": "Ada"}]
result[0]["name"] = "changed again"
assert db.query("members", ["name"]) == [{"name": "Ada"}]
for call in (
    lambda: db.create_table("members", ["id"]),
    lambda: db.insert("members", {"id": "2", "name": "Bryn"}),
    lambda: db.query("missing", ["id"]),
):
    try:
        call()
    except (KeyError, ValueError, AssertionError):
        pass
    else:
        raise AssertionError("expected an error")

db = Database()
db.create_table("members", ["id", "name", "score", "team"])
for row in (
    {"id": "1", "name": "Ada", "score": "10", "team": "red"},
    {"id": "2", "name": "Bryn", "score": "2", "team": "red"},
    {"id": "3", "name": "Cal", "score": "2", "team": "red"},
    {"id": "4", "name": "Dia", "score": "2", "team": "blue"},
):
    db.insert("members", row)
assert db.query(
    "members", ["name"], where=[("team", "=", "red")], order_by=[("score", True)]
) == [{"name": "Bryn"}, {"name": "Cal"}, {"name": "Ada"}]
assert db.query("members", ["name"], order_by=[("score", False), ("name", False)]) == [
    {"name": "Ada"},
    {"name": "Dia"},
    {"name": "Cal"},
    {"name": "Bryn"},
]
for call in (
    lambda: db.query("members", ["missing"]),
    lambda: db.query("members", ["id"], where=[("score", "~", "2")]),
    lambda: db.query("members", ["id"], order_by=[("missing", True)]),
):
    try:
        call()
    except (ValueError, AssertionError):
        pass
    else:
        raise AssertionError("expected input validation error")

db = Database()
db.create_table('scores', ['id', 'team', 'score'])
for row in (
    {'id': 'a', 'team': 'red', 'score': '2'},
    {'id': 'b', 'team': 'blue', 'score': '10'},
    {'id': 'c', 'team': 'red', 'score': 10},
    {'id': 'd', 'team': 'blue', 'score': '2'},
    {'id': 'e', 'team': 'red', 'score': '10'},
):
    db.insert('scores', row)
assert db.query('scores', ['id'], order_by=[('team', True), ('score', False)]) == [
    {'id': 'b'}, {'id': 'd'}, {'id': 'c'}, {'id': 'e'}, {'id': 'a'}
]
assert db.query('scores', ['id'], order_by=[('team', False), ('score', True)]) == [
    {'id': 'a'}, {'id': 'c'}, {'id': 'e'}, {'id': 'd'}, {'id': 'b'}
]

db = Database()
db.create_table('events', ['id', 'group', 'priority', 'active'])
for row in (
    {'id': 1, 'group': 'z', 'priority': '3', 'active': True},
    {'id': 2, 'group': 'a', 'priority': '2', 'active': False},
    {'id': 3, 'group': 'a', 'priority': '10', 'active': True},
    {'id': 4, 'group': 'a', 'priority': '2', 'active': True},
    {'id': 5, 'group': 'z', 'priority': '11', 'active': True},
):
    db.insert('events', row)
assert db.query('events', ['id'], where=[('active', '=', True), ('priority', '>=', '3')], order_by=[('group', True), ('priority', False)]) == [
    {'id': 3}, {'id': 5}, {'id': 1}
]
assert db.query('events', ['id'], where=[('group', '=', 'a')], order_by=[('priority', False), ('id', True)]) == [
    {'id': 3}, {'id': 2}, {'id': 4}
]
assert db.query('events', ['id'], where=[('priority', '<', 0)], order_by=[('group', True)]) == []
assert db.query('events', ['id'], where=[], order_by=[]) == [{'id': 1}, {'id': 2}, {'id': 3}, {'id': 4}, {'id': 5}]

